package ru.kupiora.radar;
import org.junit.*;import static org.junit.Assert.*;import java.time.*;import java.nio.file.*;import java.util.*;import org.json.*;
public class TopicsAndDigestTest {
 @Before public void load()throws Exception{Catalog.loadJson(new String(Files.readAllBytes(Paths.get("src/main/assets/topic-catalog.json")),java.nio.charset.StandardCharsets.UTF_8));}
 @Test public void variableHierarchyWithoutDuplicates(){assertEquals(12,Catalog.roots.size());assertEquals(17,Catalog.leaves("auto").size());assertEquals(21,Catalog.leaves("health").size());assertEquals(4,Catalog.leaves("environment").size());assertEquals(1,Catalog.leaves("health.endocrine").size());assertFalse(Catalog.index.containsKey("health.endocrine.diabetes"));assertEquals(159,Catalog.index.size());assertEquals(118,Catalog.roots.stream().mapToInt(t->Catalog.leaves(t.id).size()).sum());}
 @Test public void focusedSelectionDoesNotLeakSibling()throws Exception{Set<String>s=new HashSet<>(Arrays.asList("auto.osago.price.territory"));JSONObject price=new JSONObject().put("categoryId","auto").put("topicIds",new JSONArray().put("auto.osago.price"));JSONObject accident=new JSONObject().put("categoryId","auto").put("topicIds",new JSONArray().put("auto.osago.accident"));assertTrue(Store.matchesSelection(s,price));assertFalse(Store.matchesSelection(s,accident));assertFalse(Store.matchesSelection(s,new JSONObject().put("categoryId","auto")));}
 @Test public void multitagDocumentIncludedOnce()throws Exception{List<JSONObject> items=Feed.parse(new String(Files.readAllBytes(Paths.get("src/main/assets/legal-feed.json")),java.nio.charset.StandardCharsets.UTF_8));assertEquals(3,items.size());Set<String>s=new HashSet<>(Catalog.leaves("auto.osago"));assertEquals(2,items.stream().filter(x->Store.matchesSelection(s,x)).count());}
 @Test public void unknownOrForeignTopicRejected()throws Exception{JSONObject root=new JSONObject(new String(Files.readAllBytes(Paths.get("src/main/assets/legal-feed.json")),java.nio.charset.StandardCharsets.UTF_8));root.getJSONArray("items").getJSONObject(0).put("topicIds",new JSONArray().put("health.nonexistent"));assertEquals(2,Feed.parse(root.toString()).size());}
 @Test public void officialHomepageAndNewsCannotBecomeAct()throws Exception{JSONObject root=new JSONObject(new String(Files.readAllBytes(Paths.get("src/main/assets/legal-feed.json")),java.nio.charset.StandardCharsets.UTF_8));root.getJSONArray("items").getJSONObject(0).put("sourceUrl","https://www.cbr.ru/press/event/?id=123");assertEquals(2,Feed.parse(root.toString()).size());}
 @Test public void intervalsAndExactBoundary(){ZoneId zone=ZoneId.of("Europe/Moscow");long start=ZonedDateTime.of(2026,11,4,9,0,0,0,zone).toInstant().toEpochMilli();for(int days:new int[]{1,3,7}){String f=days==1?"daily":days==3?"three_days":"weekly";long due=ZonedDateTime.of(2026,11,4,9,0,0,0,zone).plusDays(days).toInstant().toEpochMilli();assertFalse(DigestPolicy.isDue(start,due-1,f,zone));assertTrue(DigestPolicy.isDue(start,due,f,zone));}}
 @Test public void collapsingDiagnosesPreservesSpecialtyChoice(){Set<String> migrated=Catalog.normalizeSelection(Arrays.asList("health.endocrine.diabetes.adult","health.cardio.followup"),true);assertEquals(new HashSet<>(Arrays.asList("health.endocrine","health.cardio")),migrated);}
 @Test public void userCanKeepEyeWithoutEarAfterMigration(){assertTrue(Catalog.normalizeSelection(Arrays.asList("health.vision"),true).contains("health.hearing"));assertFalse(Catalog.normalizeSelection(Arrays.asList("health.vision"),false).contains("health.hearing"));}
 @Test public void archiveNeverTriggersNewChangeAlert()throws Exception{JSONObject x=new JSONObject().put("id","sample").put("categoryId","auto").put("topicIds",new JSONArray().put("auto.osago.price.territory")).put("archive",true);Set<String> chosen=new HashSet<>(Catalog.leaves("auto")),seen=new HashSet<>();assertFalse(DigestPolicy.shouldQueue(x,true,seen,chosen));x.put("archive",false);assertTrue(DigestPolicy.shouldQueue(x,true,seen,chosen));assertFalse(DigestPolicy.shouldQueue(x,false,seen,chosen));seen.add("sample");assertFalse(DigestPolicy.shouldQueue(x,true,seen,chosen));}
 @Test public void sourcesInheritedByBranch(){assertEquals(Arrays.asList("cbr","pravo"),Catalog.sourcesFor("auto.osago.price.kbm"));assertTrue(Catalog.sourcesFor("health.medicines.benefit").contains("roszdrav"));assertFalse(Catalog.sourcesFor("auto.osago").contains("mvd"));}
 @Test public void monthIsCalendarMonth(){ZoneId z=ZoneId.of("Europe/Moscow");long jan=ZonedDateTime.of(2027,1,31,9,0,0,0,z).toInstant().toEpochMilli();assertEquals(LocalDate.of(2027,2,28),DigestPolicy.due(jan,"monthly",z).toLocalDate());}
}
